func ReduceRightErr[T, R any](collection []T, accumulator func(agg R, item T, index int) (R, error), initial R) (R, error) {
	for i := len(collection) - 1; i >= 0; i-- {
		result, err := accumulator(initial, collection[i], i)
		if err != nil {
			var zero R
			return zero, err
		}
		initial = result
	}

	return initial, nil
}

