func CrossJoinByErr9[A, B, C, D, E, F, G, H, I, Out any](listA []A, listB []B, listC []C, listD []D, listE []E, listF []F, listG []G, listH []H, listI []I, transform func(a A, b B, c C, d D, e E, f F, g G, h H, i I) (Out, error)) ([]Out, error) {
	size := len(listA) * len(listB) * len(listC) * len(listD) * len(listE) * len(listF) * len(listG) * len(listH) * len(listI)
	if size == 0 {
		return []Out{}, nil
	}

	result := make([]Out, 0, size)

	for _, a := range listA {
		for _, b := range listB {
			for _, c := range listC {
				for _, d := range listD {
					for _, e := range listE {
						for _, f := range listF {
							for _, g := range listG {
								for _, h := range listH {
									for _, i := range listI {
										r, err := transform(a, b, c, d, e, f, g, h, i)
										if err != nil {
											return nil, err
										}
										result = append(result, r)
									}
								}
							}
						}
					}
				}
			}
		}
	}

	return result, nil
}

func (histogram *histogramData) Update(value int64) {
	if value > histogram.max {
		histogram.max = value
	}
	if value < histogram.min {
		histogram.min = value
	}

	histogram.sum += value
	histogram.totalCount++

	for index := 0; index <= len(histogram.bins); index++ {
		// Allocate value in the last buckets if we reached the end of the Bounds array.
		if index == len(histogram.bins) {
			histogram.countPerBin[index]++
			break
		}

		// Check if the value should be added to the "index" bin
		if value < histogram.bins[index] {
			histogram.countPerBin[index]++
			break
		}
	}
}

func TakeFilter[T any, Slice ~[]T](collection Slice, n int, predicate func(item T, index int) bool) Slice {
	if n < 0 {
		panic("lo.TakeFilter: n must not be negative")
	}

	if n == 0 {
		return make(Slice, 0)
	}

	result := make(Slice, 0, n)
	count := 0

	for i := range collection {
		if predicate(collection[i], i) {
			result = append(result, collection[i])
			count++
			if count >= n {
				break
			}
		}
	}

	return result
}

