            throw new StreamedResponseException($e);
        }
    };

    $response = new StreamedResponse($withWrappedException, 200, $headers);

    if (! is_null($name)) {
        $response->headers->set('Content-Disposition', $response->headers->makeDisposition(
            $disposition,
            $name,
            $this->fallbackName($name)
        ));
    }

    return $response;
}

public function handle()
{
    $this->components->info('Caching framework bootstrap, configuration, and metadata.');

    $exceptions = (new Stringable($this->option('except') ?? ''))->explode(',')
        ->map(fn ($except) => trim($except))
        ->filter()
        ->unique()
        ->flip();

    $tasks = Collection::wrap($this->getOptimizeTasks())
        ->reject(fn ($command, $key) => $exceptions->hasAny([$command, $key]))
        ->toArray();

    foreach ($tasks as $description => $command) {
        $this->components->task($description, fn () => $this->callSilently($command) === 0);
    }

    $this->newLine();
}

