public function zadd($key, ...$dictionary)
{
    if (is_array(end($dictionary))) {
        foreach (array_pop($dictionary) as $member => $score) {
            $dictionary[] = $score;
            $dictionary[] = $member;
        }
    }

    $options = [];

    foreach (array_slice($dictionary, 0, 3) as $i => $value) {
        if (in_array($value, ['nx', 'xx', 'ch', 'incr', 'gt', 'lt', 'NX', 'XX', 'CH', 'INCR', 'GT', 'LT'], true)) {
            $options[] = $value;

            unset($dictionary[$i]);
        }
    }

    return $this->command('zadd', array_merge([$key], [$options], array_values($dictionary)));
}

public function getUser(#[\SensitiveParameter] array $credentials)
{
    $credentials = Arr::except($credentials, ['token']);

    $user = $this->users->retrieveByCredentials($credentials);

    if ($user && ! $user instanceof CanResetPasswordContract) {
        throw new UnexpectedValueException('User must implement CanResetPassword interface.');
    }

    return $user;
}

protected function createRoundrobinTransportOfClass(array $config, string $class)
{
    $transports = [];

    foreach ($config['mailers'] as $name) {
        $config = $this->getConfig($name);

        if (is_null($config)) {
            throw new InvalidArgumentException("Mailer [{$name}] is not defined.");
        }

        // Now, we will check if the "driver" key exists and if it does we will set
        // the transport configuration parameter in order to offer compatibility
        // with any Laravel <= 6.x application style mail configuration files.
        $transports[] = $this->app['config']['mail.driver']
            ? $this->createSymfonyTransport(array_merge($config, ['transport' => $name]))
            : $this->createSymfonyTransport($config);
    }

    return new $class($transports, $config['retry_after'] ?? 60, $this->app->make(LoggerInterface::class));
}

public function markAsFinished(string $batchId)
{
    if (isset($this->batches[$batchId])) {
        $this->batches[$batchId]->finishedAt = CarbonImmutable::now();
    }
}

public function whereNotIn($key, $values, $strict = false)
{
    $values = $this->getArrayableItems($values);

    return $this->reject(fn ($item) => in_array(data_get($item, $key), $values, $strict));
}

public function whereNot($column, $value)
{
    if ($value instanceof Arrayable || is_array($value)) {
        return $this->whereNotIn($column, $value);
    }

    $value = enum_value($value);

    if ($value === false) {
        $value = 0;
    }

    return $this->where($column, '!'.$value);
}

public function formatClassName(string $component)
{
    $componentPieces = array_map(function ($componentPiece) {
        return ucfirst(Str::camel($componentPiece));
    }, explode('.', $component));

    return implode('\\', $componentPieces);
}

protected function causedByLostConnection(Throwable $e)
{
    if (! $e instanceof RedisClusterException && ! $e instanceof RedisException && ! $e instanceof ErrorException) {
        return false;
    }

    return Str::contains($e->getMessage(), [
        'went away',
        'socket',
        'Error while reading',
        'read error on connection',
        'READONLY',
        'Connection lost',
        'Error processing response from Redis node',
        'Connection reset by peer',
    ]);
}

protected function dispatchEvents($databases)
{
    $databases->each(function ($database) {
        if ($database['status'] === '<fg=green;options=bold>OK</>') {
            return;
        }

        $this->events->dispatch(
            new DatabaseBusy(
                $database['database'],
                $database['connections']
            )
        );
    });
}
